import * as THREE from 'three/webgpu';
import { texture, uv, vec4, color } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'hub-journal-card-2-label';
  group.position.set(3.2, 1, 0.06);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const colors = {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  // Background plane (small accent card behind text)
  const planeGeo = new THREE.PlaneGeometry(1.4, 0.3);
  const material = new THREE.MeshBasicNodeMaterial({ transparent: true });

  let map = null;
  try {
    map = ctx.textureLoader.load('/prism-mock/home/nodes/floating-accent.png');
  } catch (e) {
    map = null;
  }

  if (map) {
    map.colorSpace = THREE.SRGBColorSpace;
    const tex = texture(map, uv());
    material.colorNode = tex.mul(vec4(1, 1, 1, 1));
  } else {
    material.colorNode = vec4(color(colors.surface), 0.0);
  }

  const plane = new THREE.Mesh(planeGeo, material);
  plane.name = 'card-label-plane';
  group.add(plane);

  // Text content: "Journal 3" headline
  let textMesh = null;
  try {
    textMesh = ctx.fontAtlas.createText({
      text: 'Journal 3',
      font: 'display',
      weight: 400,
      size: 0.34,
      color: colors.paper,
      align: 'center',
      anchor: 'center',
    });
    textMesh.position.set(0, 0, 0.01);
    group.add(textMesh);
  } catch (e) {
    // fontAtlas unavailable — fail gracefully without HTML fallback
  }

  // Interaction state
  const state = {
    hovered: false,
    baseY: group.position.y,
  };

  let hoverTween = null;
  let pressTween = null;

  const handlers = {
    onPointerOver: () => {
      if (state.hovered) return;
      state.hovered = true;
      if (hoverTween) hoverTween.kill();
      hoverTween = gsap.to(group.position, {
        y: state.baseY + 0.15,
        duration: 0.7,
        ease: 'power3.out',
      });
    },
    onPointerOut: () => {
      state.hovered = false;
      if (hoverTween) hoverTween.kill();
      hoverTween = gsap.to(group.position, {
        y: state.baseY,
        duration: 0.7,
        ease: 'power3.out',
      });
    },
    onPointerDown: () => {
      if (pressTween) pressTween.kill();
      pressTween = gsap.to(group.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'back.out',
      });
    },
    onPointerUp: () => {
      if (pressTween) pressTween.kill();
      pressTween = gsap.to(group.scale, {
        x: 1,
        y: 1,
        z: 1,
        duration: 0.12,
        ease: 'back.out',
      });
    },
    onClick: () => {
      group.userData.emit && group.userData.emit('hub-journal.select', {
        id: 'hub-journal-card-2',
      });
    },
  };

  group.userData.handlers = handlers;

  group.userData.cleanup = () => {
    if (hoverTween) hoverTween.kill();
    if (pressTween) pressTween.kill();
    gsap.killTweensOf(group.position);
    gsap.killTweensOf(group.scale);

    planeGeo.dispose();
    material.dispose();
    if (map) map.dispose();

    if (textMesh) {
      if (textMesh.geometry) textMesh.geometry.dispose();
      if (textMesh.material) textMesh.material.dispose();
    }
  };

  return group;
}
